use std::io::{self, Write};

/// How input bytes are interpreted.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Encoding {
    /// Invalid sequences are replaced with U+FFFD.
    Utf8Lossy,
    /// Invalid sequences are a hard error.
    Utf8,
}

#[derive(Clone, Debug)]
pub struct Options {
    pub hscale: f64,
    pub vscale: f64,
    pub padding: Option<usize>,
    pub encoding: Encoding,
}

/// Horizontal extent of the non-blank content of one minimap row, in
/// (byte-based) source columns, before horizontal scaling.
///
/// `beg` is the byte offset of the first non-whitespace character and `end`
/// is one past the byte offset of the last one.  A row which has seen only
/// blank lines keeps `beg == usize::MAX` (so it never widens the start of a
/// merge) and `end == 1`, which gives blank rows a nominal width of one
/// source column.
#[derive(Clone, Copy, Debug)]
struct Row {
    beg: usize,
    end: usize,
}

impl Row {
    const EMPTY: Row = Row {
        beg: usize::MAX,
        end: 1,
    };

    fn merge(&mut self, line: &str) {
        let mut first = None;
        let mut last = None;
        for (idx, ch) in line.char_indices() {
            if !ch.is_whitespace() {
                if first.is_none() {
                    first = Some(idx);
                }
                last = Some(idx);
            }
        }
        if let (Some(f), Some(l)) = (first, last) {
            self.beg = self.beg.min(f);
            self.end = self.end.max(l + 1);
        }
    }

    fn scaled(&self, hscale: f64) -> (usize, usize) {
        let beg = (self.beg as f64 * hscale) as usize;
        let end = (self.end as f64 * hscale) as usize;
        (beg, end)
    }
}

/// Dot bit for braille row `r` (0..4) and column `c` (0..2).
const DOTS: [[u8; 2]; 4] = [[0x01, 0x08], [0x02, 0x10], [0x04, 0x20], [0x40, 0x80]];

pub struct Renderer<'a, W: Write> {
    opts: &'a Options,
    out: &'a mut W,
    rows: Vec<Row>,
    cur_row: Option<usize>,
    line_no: usize,
    cells: Vec<u8>,
    text: String,
}

impl<'a, W: Write> Renderer<'a, W> {
    pub fn new(opts: &'a Options, out: &'a mut W) -> Self {
        Renderer {
            opts,
            out,
            rows: Vec::with_capacity(4),
            cur_row: None,
            line_no: 0,
            cells: Vec::new(),
            text: String::new(),
        }
    }

    /// Register the arrival of the next source line (whether or not it could
    /// actually be decoded).  Flushes a completed group of four rows when the
    /// new line starts a fresh row.
    pub fn begin_line(&mut self) -> io::Result<()> {
        let row = (self.line_no as f64 * self.opts.vscale) as usize;
        self.line_no += 1;
        if self.cur_row != Some(row) {
            if self.rows.len() == 4 {
                self.flush_rows()?;
            }
            self.rows.push(Row::EMPTY);
            self.cur_row = Some(row);
        }
        Ok(())
    }

    /// Merge the content of the current source line into the current row.
    pub fn feed(&mut self, line: &str) {
        if let Some(row) = self.rows.last_mut() {
            row.merge(line);
        }
    }

    pub fn finish(mut self) -> io::Result<()> {
        if !self.rows.is_empty() {
            self.flush_rows()?;
        }
        Ok(())
    }

    fn flush_rows(&mut self) -> io::Result<()> {
        let hscale = self.opts.hscale;
        let mut scaled = [(0usize, 0usize); 4];
        let mut width = 0usize;
        for (i, row) in self.rows.iter().enumerate() {
            let (b, e) = row.scaled(hscale);
            scaled[i] = (b, e);
            width = width.max(e);
        }
        let ncells = width / 2 + width % 2;

        let cells = &mut self.cells;
        cells.clear();
        cells.resize(ncells, 0);

        for (r, &(b, e)) in scaled.iter().enumerate().take(self.rows.len()) {
            if b >= e {
                continue;
            }
            let mut col = b;
            // Leading half cell.
            if col % 2 == 1 {
                cells[col / 2] |= DOTS[r][1];
                col += 1;
            }
            // Full cells.
            let both = DOTS[r][0] | DOTS[r][1];
            let full_end = e - (e % 2);
            if col < full_end {
                for cell in &mut cells[col / 2..full_end / 2] {
                    *cell |= both;
                }
                col = full_end;
            }
            // Trailing half cell.
            if col < e {
                cells[col / 2] |= DOTS[r][0];
            }
        }

        let text = &mut self.text;
        text.clear();
        text.reserve(ncells * 3);
        for &c in cells.iter() {
            text.push(char::from_u32(0x2800 + c as u32).unwrap_or('\u{2800}'));
        }

        match self.opts.padding {
            Some(pad) => writeln!(self.out, "{:<width$}", text, width = pad)?,
            None => writeln!(self.out, "{}", text)?,
        }

        self.rows.clear();
        Ok(())
    }
}
