//! Shell completion script generation.
//!
//! The scripts are produced by walking the (fully built) clap [`Command`]
//! tree, so they stay in sync with the CLI definition.

use std::fmt::Write as _;
use std::io::{self, Write};

use clap::{Arg, Command, ValueHint};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    PowerShell,
    Zsh,
}

impl Shell {
    pub const NAMES: [&'static str; 5] = ["bash", "elvish", "fish", "powershell", "zsh"];

    pub fn from_name(name: &str) -> Option<Shell> {
        match name {
            "bash" => Some(Shell::Bash),
            "elvish" => Some(Shell::Elvish),
            "fish" => Some(Shell::Fish),
            "powershell" => Some(Shell::PowerShell),
            "zsh" => Some(Shell::Zsh),
            _ => None,
        }
    }
}

/// Write the completion script for `shell` to `out`.
pub fn generate<W: Write>(shell: Shell, cmd: &mut Command, bin_name: &str, out: &mut W) -> io::Result<()> {
    cmd.build();
    let script = match shell {
        Shell::Bash => bash(cmd, bin_name),
        Shell::Elvish => elvish(cmd, bin_name),
        Shell::Fish => fish(cmd, bin_name),
        Shell::PowerShell => powershell(cmd, bin_name),
        Shell::Zsh => zsh(cmd, bin_name),
    };
    out.write_all(script.as_bytes())
}

// ---------------------------------------------------------------------------
// helpers

fn help_text(arg: &Arg) -> String {
    arg.get_help()
        .map(|h| h.to_string())
        .unwrap_or_default()
        .replace('\n', " ")
}

fn about_text(cmd: &Command) -> String {
    cmd.get_about()
        .map(|h| h.to_string())
        .unwrap_or_default()
        .replace('\n', " ")
}

fn possible_values(arg: &Arg) -> Vec<String> {
    arg.get_possible_values()
        .iter()
        .filter(|v| !v.is_hide_set())
        .map(|v| v.get_name().to_string())
        .collect()
}

fn takes_value(arg: &Arg) -> bool {
    arg.get_action().takes_values()
}

fn visible_args(cmd: &Command) -> impl Iterator<Item = &Arg> {
    cmd.get_arguments().filter(|a| !a.is_hide_set())
}

fn visible_opts(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| !a.is_positional() && takes_value(a))
}

fn visible_flags(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| !a.is_positional() && !takes_value(a))
}

fn visible_positionals(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| a.is_positional())
}

fn visible_subcommands(cmd: &Command) -> impl Iterator<Item = &Command> {
    cmd.get_subcommands().filter(|c| !c.is_hide_set())
}

fn shorts(arg: &Arg) -> Vec<char> {
    let mut v = Vec::new();
    if let Some(s) = arg.get_short() {
        v.push(s);
    }
    if let Some(aliases) = arg.get_visible_short_aliases() {
        v.extend(aliases);
    }
    v
}

fn longs(arg: &Arg) -> Vec<String> {
    let mut v = Vec::new();
    if let Some(l) = arg.get_long() {
        v.push(l.to_string());
    }
    if let Some(aliases) = arg.get_visible_aliases() {
        v.extend(aliases.into_iter().map(|s| s.to_string()));
    }
    v
}

/// Flattened command tree: every command together with the path of
/// subcommand names leading to it (the root has an empty path).
fn walk<'a>(cmd: &'a Command, path: Vec<&'a str>, acc: &mut Vec<(Vec<&'a str>, &'a Command)>) {
    acc.push((path.clone(), cmd));
    for sub in visible_subcommands(cmd) {
        let mut p = path.clone();
        p.push(sub.get_name());
        walk(sub, p, acc);
    }
}

fn all_commands(cmd: &Command) -> Vec<(Vec<&str>, &Command)> {
    let mut acc = Vec::new();
    walk(cmd, Vec::new(), &mut acc);
    acc
}

fn single_quote(s: &str) -> String {
    s.replace('\'', "'\\''")
}

// ---------------------------------------------------------------------------
// bash

fn bash(cmd: &Command, bin_name: &str) -> String {
    let func = format!("_{}", bin_name);
    let root_id = bin_name.replace('-', "__");
    let cmds = all_commands(cmd);

    let mut cases = String::new();
    for (path, c) in &cmds {
        let id = bash_cmd_id(&root_id, path);
        for sub in visible_subcommands(c) {
            let mut p = path.clone();
            p.push(sub.get_name());
            let sub_id = bash_cmd_id(&root_id, &p);
            let _ = write!(
                cases,
                "            {id},{name})\n                cmd=\"{sub_id}\"\n                ;;\n",
                id = id,
                name = sub.get_name(),
                sub_id = sub_id
            );
        }
    }

    let mut bodies = String::new();
    for (path, c) in &cmds {
        let id = bash_cmd_id(&root_id, path);
        let level = path.len() + 1;

        let mut opts: Vec<String> = Vec::new();
        for a in visible_args(c).filter(|a| !a.is_positional()) {
            for s in shorts(a) {
                opts.push(format!("-{}", s));
            }
        }
        for a in visible_args(c).filter(|a| !a.is_positional()) {
            for l in longs(a) {
                opts.push(format!("--{}", l));
            }
        }
        for a in visible_positionals(c) {
            let vals = possible_values(a);
            if vals.is_empty() {
                opts.push(a.to_string());
            } else {
                opts.extend(vals);
            }
        }
        for sub in visible_subcommands(c) {
            opts.push(sub.get_name().to_string());
        }

        let mut prev_cases = String::new();
        for a in visible_opts(c) {
            let vals = possible_values(a);
            let completion = if vals.is_empty() {
                "COMPREPLY=($(compgen -f \"${cur}\"))".to_string()
            } else {
                format!("COMPREPLY=($(compgen -W \"{}\" -- \"${{cur}}\"))", vals.join(" "))
            };
            for l in longs(a) {
                let _ = write!(
                    prev_cases,
                    "                --{l})\n                    {completion}\n                    return 0\n                    ;;\n",
                    l = l,
                    completion = completion
                );
            }
            for s in shorts(a) {
                let _ = write!(
                    prev_cases,
                    "                -{s})\n                    {completion}\n                    return 0\n                    ;;\n",
                    s = s,
                    completion = completion
                );
            }
        }

        let _ = write!(
            bodies,
            "        {id})
            opts=\"{opts}\"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq {level} ]] ; then
                COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
                return 0
            fi
            case \"${{prev}}\" in
{prev_cases}                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
            return 0
            ;;
",
            id = id,
            opts = opts.join(" "),
            level = level,
            prev_cases = prev_cases
        );
    }

    format!(
        "{func}() {{
    local i cur prev opts cmd
    COMPREPLY=()
    cur=\"${{COMP_WORDS[COMP_CWORD]}}\"
    prev=\"${{COMP_WORDS[COMP_CWORD-1]}}\"
    cmd=\"\"
    opts=\"\"

    for i in ${{COMP_WORDS[@]}}
    do
        case \"${{cmd}},${{i}}\" in
            \",$1\")
                cmd=\"{root_id}\"
                ;;
{cases}            *)
                ;;
        esac
    done

    case \"${{cmd}}\" in
{bodies}    esac
}}

if [[ \"${{BASH_VERSINFO[0]}}\" -eq 4 && \"${{BASH_VERSINFO[1]}}\" -ge 4 || \"${{BASH_VERSINFO[0]}}\" -gt 4 ]]; then
    complete -F {func} -o nosort -o bashdefault -o default {bin}
else
    complete -F {func} -o bashdefault -o default {bin}
fi
",
        func = func,
        root_id = root_id,
        cases = cases,
        bodies = bodies,
        bin = bin_name
    )
}

fn bash_cmd_id(root_id: &str, path: &[&str]) -> String {
    let mut id = root_id.to_string();
    for p in path {
        id.push_str("__");
        id.push_str(&p.replace('-', "__"));
    }
    id
}

// ---------------------------------------------------------------------------
// zsh

fn zsh(cmd: &Command, bin_name: &str) -> String {
    let func = format!("_{}", bin_name);
    let mut body = String::new();
    zsh_command(cmd, bin_name, &[], &mut body);

    let mut describe = String::new();
    for (path, c) in all_commands(cmd) {
        let fname = zsh_commands_fn(bin_name, &path);
        let mut desc_name = bin_name.to_string();
        for p in &path {
            desc_name.push(' ');
            desc_name.push_str(p);
        }
        let subs: Vec<&Command> = visible_subcommands(c).collect();
        let _ = write!(describe, "(( $+functions[{f}] )) ||\n{f}() {{\n", f = fname);
        if subs.is_empty() {
            describe.push_str("    local commands; commands=()\n");
        } else {
            describe.push_str("    local commands; commands=(\n");
            for sub in subs {
                let _ = write!(
                    describe,
                    "'{name}:{about}' \\\n",
                    name = sub.get_name(),
                    about = single_quote(&about_text(sub))
                );
            }
            describe.push_str("    )\n");
        }
        let _ = write!(
            describe,
            "    _describe -t commands '{desc} commands' commands \"$@\"\n}}\n",
            desc = desc_name
        );
    }

    format!(
        "#compdef {bin}

autoload -U is-at-least

{func}() {{
    typeset -A opt_args
    typeset -a _arguments_options
    local ret=1

    if is-at-least 5.2; then
        _arguments_options=(-s -S -C)
    else
        _arguments_options=(-s -C)
    fi

    local context curcontext=\"$curcontext\" state line
{body}}}

{describe}
if [ \"$funcstack[1]\" = \"{func}\" ]; then
    {func} \"$@\"
else
    compdef {func} {bin}
fi
",
        bin = bin_name,
        func = func,
        body = body,
        describe = describe
    )
}

fn zsh_commands_fn(bin_name: &str, path: &[&str]) -> String {
    let mut f = format!("_{}", bin_name);
    for p in path {
        f.push_str("__");
        f.push_str(p);
    }
    f.push_str("_commands");
    f
}

fn zsh_value_completion(arg: &Arg, positional: bool) -> String {
    let vals = possible_values(arg);
    if !vals.is_empty() {
        return format!("({})", vals.join(" "));
    }
    match arg.get_value_hint() {
        ValueHint::Unknown => {
            if positional {
                "_files".to_string()
            } else {
                "_default".to_string()
            }
        }
        ValueHint::Other => String::new(),
        ValueHint::AnyPath | ValueHint::FilePath => "_files".to_string(),
        ValueHint::DirPath => "_files -/".to_string(),
        ValueHint::ExecutablePath => "_absolute_command_paths".to_string(),
        ValueHint::CommandName => "_command_names -e".to_string(),
        ValueHint::CommandString => "_cmdstring".to_string(),
        ValueHint::CommandWithArguments => "_cmdambivalent".to_string(),
        ValueHint::Username => "_users".to_string(),
        ValueHint::Hostname => "_hosts".to_string(),
        ValueHint::Url => "_urls".to_string(),
        ValueHint::EmailAddress => "_email_addresses".to_string(),
        _ => String::new(),
    }
}

fn zsh_command(cmd: &Command, bin_name: &str, path: &[&str], out: &mut String) {
    let depth = path.len();
    let state_name = if depth == 0 {
        bin_name.to_string()
    } else {
        path[depth - 1].to_string()
    };
    let indent = if depth == 0 { "    " } else { "" };

    let _ = write!(out, "{}_arguments \"${{_arguments_options[@]}}\" : \\\n", indent);

    for a in visible_opts(cmd) {
        let help = single_quote(&help_text(a));
        let value_name = a
            .get_value_names()
            .and_then(|v| v.first())
            .map(|s| s.to_string())
            .unwrap_or_else(|| a.get_id().to_string().to_uppercase());
        let completion = zsh_value_completion(a, false);
        for s in shorts(a) {
            let _ = write!(out, "'-{s}+[{help}]:{vn}:{c}' \\\n", s = s, help = help, vn = value_name, c = completion);
        }
        for l in longs(a) {
            let _ = write!(out, "'--{l}=[{help}]:{vn}:{c}' \\\n", l = l, help = help, vn = value_name, c = completion);
        }
    }
    for a in visible_flags(cmd) {
        let help = single_quote(&help_text(a));
        for s in shorts(a) {
            let _ = write!(out, "'-{s}[{help}]' \\\n", s = s, help = help);
        }
        for l in longs(a) {
            let _ = write!(out, "'--{l}[{help}]' \\\n", l = l, help = help);
        }
    }
    for a in visible_positionals(cmd) {
        let cardinality = if a.get_num_args().map(|n| n.max_values() > 1).unwrap_or(false) {
            "*"
        } else if a.is_required_set() {
            ""
        } else {
            ":"
        };
        let help = help_text(a);
        let help = if help.is_empty() {
            String::new()
        } else {
            format!(" -- {}", single_quote(&help))
        };
        let completion = zsh_value_completion(a, true);
        let _ = write!(
            out,
            "'{card}:{name}{help}:{c}' \\\n",
            card = cardinality,
            name = a.get_id(),
            help = help,
            c = completion
        );
    }

    let subs: Vec<&Command> = visible_subcommands(cmd).collect();
    if !subs.is_empty() {
        let _ = write!(out, "\":: :{}\" \\\n", zsh_commands_fn(bin_name, path));
        let _ = write!(out, "\"*::: :->{}\" \\\n", state_name);
    }
    out.push_str("&& ret=0\n");

    if subs.is_empty() {
        return;
    }

    let line_idx = if depth == 0 { 2 } else { 1 };
    let mut ctx_name = bin_name.to_string();
    for p in path {
        ctx_name.push('-');
        ctx_name.push_str(p);
    }
    if depth > 0 {
        out.push('\n');
    }
    let _ = write!(
        out,
        "    case $state in
    ({state})
        words=($line[{idx}] \"${{words[@]}}\")
        (( CURRENT += 1 ))
        curcontext=\"${{curcontext%:*:*}}:{ctx}-command-$line[{idx}]:\"
        case $line[{idx}] in
",
        state = state_name,
        idx = line_idx,
        ctx = ctx_name
    );
    let mut first = true;
    for sub in subs {
        if first {
            let _ = write!(out, "            ({})\n", sub.get_name());
            first = false;
        } else {
            let _ = write!(out, "({})\n", sub.get_name());
        }
        let mut p = path.to_vec();
        p.push(sub.get_name());
        zsh_command(sub, bin_name, &p, out);
        out.push_str(";;\n");
    }
    out.push_str("        esac\n    ;;\nesac\n");
}

// ---------------------------------------------------------------------------
// fish

fn fish(cmd: &Command, bin_name: &str) -> String {
    let fn_base = format!("__fish_{}", bin_name.replace('-', "_"));

    let mut optspecs: Vec<String> = Vec::new();
    for a in visible_args(cmd).filter(|a| !a.is_positional()) {
        let mut spec = String::new();
        let sh = shorts(a);
        let lo = longs(a);
        if let Some(s) = sh.first() {
            spec.push(*s);
        }
        if let Some(l) = lo.first() {
            if !spec.is_empty() {
                spec.push('/');
            }
            spec.push_str(l);
        }
        if takes_value(a) {
            spec.push('=');
        }
        optspecs.push(spec);
    }

    let mut out = format!(
        "# Print an optspec for argparse to handle cmd's options that are independent of any subcommand.
function {base}_global_optspecs
\tstring join \\n {specs}
end

function {base}_needs_command
\t# Figure out if the current invocation already has a command.
\tset -l cmd (commandline -opc)
\tset -e cmd[1]
\targparse -s ({base}_global_optspecs) -- $cmd 2>/dev/null
\tor return
\tif set -q argv[1]
\t\t# Also print the command, so this can be used to figure out what it is.
\t\techo $argv[1]
\t\treturn 1
\tend
\treturn 0
end

function {base}_using_subcommand
\tset -l cmd ({base}_needs_command)
\ttest -z \"$cmd\"
\tand return 1
\tcontains -- $cmd[1] $argv
end

",
        base = fn_base,
        specs = optspecs.join(" ")
    );

    for (path, c) in all_commands(cmd) {
        let condition = match path.len() {
            0 => format!("{}_needs_command", fn_base),
            1 => {
                let subs: Vec<&str> = visible_subcommands(c).map(|s| s.get_name()).collect();
                if subs.is_empty() {
                    format!("{}_using_subcommand {}", fn_base, path[0])
                } else {
                    format!(
                        "{}_using_subcommand {}; and not __fish_seen_subcommand_from {}",
                        fn_base,
                        path[0],
                        subs.join(" ")
                    )
                }
            }
            _ => {
                let mut cond = format!("{}_using_subcommand {}", fn_base, path[0]);
                for p in &path[1..] {
                    let _ = write!(cond, "; and __fish_seen_subcommand_from {}", p);
                }
                let subs: Vec<&str> = visible_subcommands(c).map(|s| s.get_name()).collect();
                if !subs.is_empty() {
                    let _ = write!(cond, "; and not __fish_seen_subcommand_from {}", subs.join(" "));
                }
                cond
            }
        };
        let preamble = format!("complete -c {} -n \"{}\"", bin_name, condition);

        for a in visible_args(c).filter(|a| !a.is_positional()) {
            let mut line = preamble.clone();
            for s in shorts(a) {
                let _ = write!(line, " -s {}", s);
            }
            for l in longs(a) {
                let _ = write!(line, " -l {}", l);
            }
            let help = help_text(a);
            if !help.is_empty() {
                let _ = write!(line, " -d '{}'", single_quote(&help));
            }
            if takes_value(a) {
                line.push_str(" -r");
                let vals = possible_values(a);
                if !vals.is_empty() {
                    let items: Vec<String> = vals.iter().map(|v| format!("{}\\t''", v)).collect();
                    let _ = write!(line, " -f -a \"{{{}}}\"", items.join(","));
                } else {
                    match a.get_value_hint() {
                        ValueHint::Unknown | ValueHint::AnyPath | ValueHint::FilePath => {}
                        ValueHint::Other => line.push_str(" -f"),
                        ValueHint::DirPath => line.push_str(" -f -a \"(__fish_complete_directories)\""),
                        ValueHint::ExecutablePath => line.push_str(" -f -a \"(__fish_complete_command)\""),
                        ValueHint::CommandName | ValueHint::CommandString | ValueHint::CommandWithArguments => {
                            line.push_str(" -f -a \"(__fish_complete_command)\"")
                        }
                        ValueHint::Username => line.push_str(" -f -a \"(__fish_complete_users)\""),
                        ValueHint::Hostname => line.push_str(" -f -a \"(__fish_print_hostnames)\""),
                        _ => {}
                    }
                }
            }
            line.push('\n');
            out.push_str(&line);
        }

        for sub in visible_subcommands(c) {
            let mut line = preamble.clone();
            if path.is_empty() {
                let _ = write!(line, " -a \"{}\"", sub.get_name());
            } else {
                let _ = write!(line, " -f -a \"{}\"", sub.get_name());
            }
            let about = about_text(sub);
            if !about.is_empty() {
                let _ = write!(line, " -d '{}'", single_quote(&about));
            }
            line.push('\n');
            out.push_str(&line);
        }
    }

    out
}

// ---------------------------------------------------------------------------
// elvish

fn elvish(cmd: &Command, bin_name: &str) -> String {
    let mut entries = String::new();
    for (path, c) in all_commands(cmd) {
        let mut key = bin_name.to_string();
        for p in &path {
            key.push(';');
            key.push_str(p);
        }
        let _ = write!(entries, "        &'{}'= {{\n", key);
        for a in visible_opts(c) {
            let help = single_quote(&help_text(a));
            for s in shorts(a) {
                let _ = write!(entries, "            cand -{} '{}'\n", s, help);
            }
            for l in longs(a) {
                let _ = write!(entries, "            cand --{} '{}'\n", l, help);
            }
        }
        for a in visible_flags(c) {
            let help = single_quote(&help_text(a));
            for s in shorts(a) {
                let _ = write!(entries, "            cand -{} '{}'\n", s, help);
            }
            for l in longs(a) {
                let _ = write!(entries, "            cand --{} '{}'\n", l, help);
            }
        }
        for sub in visible_subcommands(c) {
            let _ = write!(
                entries,
                "            cand {} '{}'\n",
                sub.get_name(),
                single_quote(&about_text(sub))
            );
        }
        entries.push_str("        }\n");
    }

    format!(
        "
use builtin;
use str;

set edit:completion:arg-completer[{bin}] = {{|@words|
    fn spaces {{|n|
        builtin:repeat $n ' ' | str:join ''
    }}
    fn cand {{|text desc|
        edit:complex-candidate $text &display=$text' '(spaces (- 14 (wcswidth $text)))$desc
    }}
    var command = '{bin}'
    for word $words[1..-1] {{
        if (str:has-prefix $word '-') {{
            break
        }}
        set command = $command';'$word
    }}
    var completions = [
{entries}    ]
    $completions[$command]
}}
",
        bin = bin_name,
        entries = entries
    )
}

// ---------------------------------------------------------------------------
// powershell

fn powershell(cmd: &Command, bin_name: &str) -> String {
    let mut entries = String::new();
    for (path, c) in all_commands(cmd) {
        let mut key = bin_name.to_string();
        for p in &path {
            key.push(';');
            key.push_str(p);
        }
        let _ = write!(entries, "        '{}' {{\n", key);
        let mut emit_arg = |a: &Arg| {
            let help = help_text(a);
            for s in shorts(a) {
                let tooltip = if help.is_empty() { format!("-{}", s) } else { help.clone() };
                // PowerShell is case-insensitive; distinguish upper-case
                // short flags with a trailing space.
                let list_item = if s.is_uppercase() {
                    format!("-{} ", s)
                } else {
                    format!("-{}", s)
                };
                let _ = write!(
                    entries,
                    "            [CompletionResult]::new('-{}', '{}', [CompletionResultType]::ParameterName, '{}')\n",
                    s,
                    list_item,
                    single_quote(&tooltip)
                );
            }
            for l in longs(a) {
                let tooltip = if help.is_empty() { format!("--{}", l) } else { help.clone() };
                let _ = write!(
                    entries,
                    "            [CompletionResult]::new('--{}', '--{}', [CompletionResultType]::ParameterName, '{}')\n",
                    l,
                    l,
                    single_quote(&tooltip)
                );
            }
        };
        for a in visible_opts(c) {
            emit_arg(a);
        }
        for a in visible_flags(c) {
            emit_arg(a);
        }
        for sub in visible_subcommands(c) {
            let about = about_text(sub);
            let tooltip = if about.is_empty() { sub.get_name().to_string() } else { about };
            let _ = write!(
                entries,
                "            [CompletionResult]::new('{}', '{}', [CompletionResultType]::ParameterValue, '{}')\n",
                sub.get_name(),
                sub.get_name(),
                single_quote(&tooltip)
            );
        }
        entries.push_str("            break\n        }\n");
    }

    format!(
        "
using namespace System.Management.Automation
using namespace System.Management.Automation.Language

Register-ArgumentCompleter -Native -CommandName '{bin}' -ScriptBlock {{
    param($wordToComplete, $commandAst, $cursorPosition)

    $commandElements = $commandAst.CommandElements
    $command = @(
        '{bin}'
        for ($i = 1; $i -lt $commandElements.Count; $i++) {{
            $element = $commandElements[$i]
            if ($element -isnot [StringConstantExpressionAst] -or
                $element.StringConstantType -ne [StringConstantType]::BareWord -or
                $element.Value.StartsWith('-') -or
                $element.Value -eq $wordToComplete) {{
                break
        }}
        $element.Value
    }}) -join ';'

    $completions = @(switch ($command) {{
{entries}    }})

    $completions.Where{{ $_.CompletionText -like \"$wordToComplete*\" }} |
        Sort-Object -Property ListItemText
}}
",
        bin = bin_name,
        entries = entries
    )
}
EOF
echo done"}

actions.command:
cd /workspace; cat > src/completion.rs <<'EOF'
//! Shell completion script generation.
//!
//! The scripts are produced by walking the (fully built) clap [`Command`]
//! tree, so they stay in sync with the CLI definition.

use std::fmt::Write as _;
use std::io::{self, Write};

use clap::{Arg, Command, ValueHint};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    PowerShell,
    Zsh,
}

impl Shell {
    pub const NAMES: [&'static str; 5] = ["bash", "elvish", "fish", "powershell", "zsh"];

    pub fn from_name(name: &str) -> Option<Shell> {
        match name {
            "bash" => Some(Shell::Bash),
            "elvish" => Some(Shell::Elvish),
            "fish" => Some(Shell::Fish),
            "powershell" => Some(Shell::PowerShell),
            "zsh" => Some(Shell::Zsh),
            _ => None,
        }
    }
}

/// Write the completion script for `shell` to `out`.
pub fn generate<W: Write>(shell: Shell, cmd: &mut Command, bin_name: &str, out: &mut W) -> io::Result<()> {
    cmd.build();
    let script = match shell {
        Shell::Bash => bash(cmd, bin_name),
        Shell::Elvish => elvish(cmd, bin_name),
        Shell::Fish => fish(cmd, bin_name),
        Shell::PowerShell => powershell(cmd, bin_name),
        Shell::Zsh => zsh(cmd, bin_name),
    };
    out.write_all(script.as_bytes())
}

// ---------------------------------------------------------------------------
// helpers

fn help_text(arg: &Arg) -> String {
    arg.get_help()
        .map(|h| h.to_string())
        .unwrap_or_default()
        .replace('\n', " ")
}

fn about_text(cmd: &Command) -> String {
    cmd.get_about()
        .map(|h| h.to_string())
        .unwrap_or_default()
        .replace('\n', " ")
}

fn possible_values(arg: &Arg) -> Vec<String> {
    arg.get_possible_values()
        .iter()
        .filter(|v| !v.is_hide_set())
        .map(|v| v.get_name().to_string())
        .collect()
}

fn takes_value(arg: &Arg) -> bool {
    arg.get_action().takes_values()
}

fn visible_args(cmd: &Command) -> impl Iterator<Item = &Arg> {
    cmd.get_arguments().filter(|a| !a.is_hide_set())
}

fn visible_opts(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| !a.is_positional() && takes_value(a))
}

fn visible_flags(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| !a.is_positional() && !takes_value(a))
}

fn visible_positionals(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| a.is_positional())
}

fn visible_subcommands(cmd: &Command) -> impl Iterator<Item = &Command> {
    cmd.get_subcommands().filter(|c| !c.is_hide_set())
}

fn shorts(arg: &Arg) -> Vec<char> {
    let mut v = Vec::new();
    if let Some(s) = arg.get_short() {
        v.push(s);
    }
    if let Some(aliases) = arg.get_visible_short_aliases() {
        v.extend(aliases);
    }
    v
}

fn longs(arg: &Arg) -> Vec<String> {
    let mut v = Vec::new();
    if let Some(l) = arg.get_long() {
        v.push(l.to_string());
    }
    if let Some(aliases) = arg.get_visible_aliases() {
        v.extend(aliases.into_iter().map(|s| s.to_string()));
    }
    v
}

/// Flattened command tree: every command together with the path of
/// subcommand names leading to it (the root has an empty path).
fn walk<'a>(cmd: &'a Command, path: Vec<&'a str>, acc: &mut Vec<(Vec<&'a str>, &'a Command)>) {
    acc.push((path.clone(), cmd));
    for sub in visible_subcommands(cmd) {
        let mut p = path.clone();
        p.push(sub.get_name());
        walk(sub, p, acc);
    }
}

fn all_commands(cmd: &Command) -> Vec<(Vec<&str>, &Command)> {
    let mut acc = Vec::new();
    walk(cmd, Vec::new(), &mut acc);
    acc
}

fn single_quote(s: &str) -> String {
    s.replace('\'', "'\\''")
}

// ---------------------------------------------------------------------------
// bash

fn bash(cmd: &Command, bin_name: &str) -> String {
    let func = format!("_{}", bin_name);
    let root_id = bin_name.replace('-', "__");
    let cmds = all_commands(cmd);

    let mut cases = String::new();
    for (path, c) in &cmds {
        let id = bash_cmd_id(&root_id, path);
        for sub in visible_subcommands(c) {
            let mut p = path.clone();
            p.push(sub.get_name());
            let sub_id = bash_cmd_id(&root_id, &p);
            let _ = write!(
                cases,
                "            {id},{name})\n                cmd=\"{sub_id}\"\n                ;;\n",
                id = id,
                name = sub.get_name(),
                sub_id = sub_id
            );
        }
    }

    let mut bodies = String::new();
    for (path, c) in &cmds {
        let id = bash_cmd_id(&root_id, path);
        let level = path.len() + 1;

        let mut opts: Vec<String> = Vec::new();
        for a in visible_args(c).filter(|a| !a.is_positional()) {
            for s in shorts(a) {
                opts.push(format!("-{}", s));
            }
        }
        for a in visible_args(c).filter(|a| !a.is_positional()) {
            for l in longs(a) {
                opts.push(format!("--{}", l));
            }
        }
        for a in visible_positionals(c) {
            let vals = possible_values(a);
            if vals.is_empty() {
                opts.push(a.to_string());
            } else {
                opts.extend(vals);
            }
        }
        for sub in visible_subcommands(c) {
            opts.push(sub.get_name().to_string());
        }

        let mut prev_cases = String::new();
        for a in visible_opts(c) {
            let vals = possible_values(a);
            let completion = if vals.is_empty() {
                "COMPREPLY=($(compgen -f \"${cur}\"))".to_string()
            } else {
                format!("COMPREPLY=($(compgen -W \"{}\" -- \"${{cur}}\"))", vals.join(" "))
            };
            for l in longs(a) {
                let _ = write!(
                    prev_cases,
                    "                --{l})\n                    {completion}\n                    return 0\n                    ;;\n",
                    l = l,
                    completion = completion
                );
            }
            for s in shorts(a) {
                let _ = write!(
                    prev_cases,
                    "                -{s})\n                    {completion}\n                    return 0\n                    ;;\n",
                    s = s,
                    completion = completion
                );
            }
        }

        let _ = write!(
            bodies,
            "        {id})
            opts=\"{opts}\"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq {level} ]] ; then
                COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
                return 0
            fi
            case \"${{prev}}\" in
{prev_cases}                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
            return 0
            ;;
",
            id = id,
            opts = opts.join(" "),
            level = level,
            prev_cases = prev_cases
        );
    }

    format!(
        "{func}() {{
    local i cur prev opts cmd
    COMPREPLY=()
    cur=\"${{COMP_WORDS[COMP_CWORD]}}\"
    prev=\"${{COMP_WORDS[COMP_CWORD-1]}}\"
    cmd=\"\"
    opts=\"\"

    for i in ${{COMP_WORDS[@]}}
    do
        case \"${{cmd}},${{i}}\" in
            \",$1\")
                cmd=\"{root_id}\"
                ;;
{cases}            *)
                ;;
        esac
    done

    case \"${{cmd}}\" in
{bodies}    esac
}}

if [[ \"${{BASH_VERSINFO[0]}}\" -eq 4 && \"${{BASH_VERSINFO[1]}}\" -ge 4 || \"${{BASH_VERSINFO[0]}}\" -gt 4 ]]; then
    complete -F {func} -o nosort -o bashdefault -o default {bin}
else
    complete -F {func} -o bashdefault -o default {bin}
fi
",
        func = func,
        root_id = root_id,
        cases = cases,
        bodies = bodies,
        bin = bin_name
    )
}

fn bash_cmd_id(root_id: &str, path: &[&str]) -> String {
    let mut id = root_id.to_string();
    for p in path {
        id.push_str("__");
        id.push_str(&p.replace('-', "__"));
    }
    id
}

// ---------------------------------------------------------------------------
// zsh

fn zsh(cmd: &Command, bin_name: &str) -> String {
    let func = format!("_{}", bin_name);
    let mut body = String::new();
    zsh_command(cmd, bin_name, &[], &mut body);

    let mut describe = String::new();
    for (path, c) in all_commands(cmd) {
        let fname = zsh_commands_fn(bin_name, &path);
        let mut desc_name = bin_name.to_string();
        for p in &path {
            desc_name.push(' ');
            desc_name.push_str(p);
        }
        let subs: Vec<&Command> = visible_subcommands(c).collect();
        let _ = write!(describe, "(( $+functions[{f}] )) ||\n{f}() {{\n", f = fname);
        if subs.is_empty() {
            describe.push_str("    local commands; commands=()\n");
        } else {
            describe.push_str("    local commands; commands=(\n");
            for sub in subs {
                let _ = write!(
                    describe,
                    "'{name}:{about}' \\\n",
                    name = sub.get_name(),
                    about = single_quote(&about_text(sub))
                );
            }
            describe.push_str("    )\n");
        }
        let _ = write!(
            describe,
            "    _describe -t commands '{desc} commands' commands \"$@\"\n}}\n",
            desc = desc_name
        );
    }

    format!(
        "#compdef {bin}

autoload -U is-at-least

{func}() {{
    typeset -A opt_args
    typeset -a _arguments_options
    local ret=1

    if is-at-least 5.2; then
        _arguments_options=(-s -S -C)
    else
        _arguments_options=(-s -C)
    fi

    local context curcontext=\"$curcontext\" state line
{body}}}

{describe}
if [ \"$funcstack[1]\" = \"{func}\" ]; then
    {func} \"$@\"
else
    compdef {func} {bin}
fi
",
        bin = bin_name,
        func = func,
        body = body,
        describe = describe
    )
}

fn zsh_commands_fn(bin_name: &str, path: &[&str]) -> String {
    let mut f = format!("_{}", bin_name);
    for p in path {
        f.push_str("__");
        f.push_str(p);
    }
    f.push_str("_commands");
    f
}

fn zsh_value_completion(arg: &Arg, positional: bool) -> String {
    let vals = possible_values(arg);
    if !vals.is_empty() {
        return format!("({})", vals.join(" "));
    }
    match arg.get_value_hint() {
        ValueHint::Unknown => {
            if positional {
                "_files".to_string()
            } else {
                "_default".to_string()
            }
        }
        ValueHint::Other => String::new(),
        ValueHint::AnyPath | ValueHint::FilePath => "_files".to_string(),
        ValueHint::DirPath => "_files -/".to_string(),
        ValueHint::ExecutablePath => "_absolute_command_paths".to_string(),
        ValueHint::CommandName => "_command_names -e".to_string(),
        ValueHint::CommandString => "_cmdstring".to_string(),
        ValueHint::CommandWithArguments => "_cmdambivalent".to_string(),
        ValueHint::Username => "_users".to_string(),
        ValueHint::Hostname => "_hosts".to_string(),
        ValueHint::Url => "_urls".to_string(),
        ValueHint::EmailAddress => "_email_addresses".to_string(),
        _ => String::new(),
    }
}

fn zsh_command(cmd: &Command, bin_name: &str, path: &[&str], out: &mut String) {
    let depth = path.len();
    let state_name = if depth == 0 {
        bin_name.to_string()
    } else {
        path[depth - 1].to_string()
    };
    let indent = if depth == 0 { "    " } else { "" };

    let _ = write!(out, "{}_arguments \"${{_arguments_options[@]}}\" : \\\n", indent);

    for a in visible_opts(cmd) {
        let help = single_quote(&help_text(a));
        let value_name = a
            .get_value_names()
            .and_then(|v| v.first())
            .map(|s| s.to_string())
            .unwrap_or_else(|| a.get_id().to_string().to_uppercase());
        let completion = zsh_value_completion(a, false);
        for s in shorts(a) {
            let _ = write!(out, "'-{s}+[{help}]:{vn}:{c}' \\\n", s = s, help = help, vn = value_name, c = completion);
        }
        for l in longs(a) {
            let _ = write!(out, "'--{l}=[{help}]:{vn}:{c}' \\\n", l = l, help = help, vn = value_name, c = completion);
        }
    }
    for a in visible_flags(cmd) {
        let help = single_quote(&help_text(a));
        for s in shorts(a) {
            let _ = write!(out, "'-{s}[{help}]' \\\n", s = s, help = help);
        }
        for l in longs(a) {
            let _ = write!(out, "'--{l}[{help}]' \\\n", l = l, help = help);
        }
    }
    for a in visible_positionals(cmd) {
        let cardinality = if a.get_num_args().map(|n| n.max_values() > 1).unwrap_or(false) {
            "*"
        } else if a.is_required_set() {
            ""
        } else {
            ":"
        };
        let help = help_text(a);
        let help = if help.is_empty() {
            String::new()
        } else {
            format!(" -- {}", single_quote(&help))
        };
        let completion = zsh_value_completion(a, true);
        let _ = write!(
            out,
            "'{card}:{name}{help}:{c}' \\\n",
            card = cardinality,
            name = a.get_id(),
            help = help,
            c = completion
        );
    }

    let subs: Vec<&Command> = visible_subcommands(cmd).collect();
    if !subs.is_empty() {
        let _ = write!(out, "\":: :{}\" \\\n", zsh_commands_fn(bin_name, path));
        let _ = write!(out, "\"*::: :->{}\" \\\n", state_name);
    }
    out.push_str("&& ret=0\n");

    if subs.is_empty() {
        return;
    }

    let line_idx = if depth == 0 { 2 } else { 1 };
    let mut ctx_name = bin_name.to_string();
    for p in path {
        ctx_name.push('-');
        ctx_name.push_str(p);
    }
    if depth > 0 {
        out.push('\n');
    }
    let _ = write!(
        out,
        "    case $state in
    ({state})
        words=($line[{idx}] \"${{words[@]}}\")
        (( CURRENT += 1 ))
        curcontext=\"${{curcontext%:*:*}}:{ctx}-command-$line[{idx}]:\"
        case $line[{idx}] in
",
        state = state_name,
        idx = line_idx,
        ctx = ctx_name
    );
    let mut first = true;
    for sub in subs {
        if first {
            let _ = write!(out, "            ({})\n", sub.get_name());
            first = false;
        } else {
            let _ = write!(out, "({})\n", sub.get_name());
        }
        let mut p = path.to_vec();
        p.push(sub.get_name());
        zsh_command(sub, bin_name, &p, out);
        out.push_str(";;\n");
    }
    out.push_str("        esac\n    ;;\nesac\n");
}

// ---------------------------------------------------------------------------
// fish

fn fish(cmd: &Command, bin_name: &str) -> String {
    let fn_base = format!("__fish_{}", bin_name.replace('-', "_"));

    let mut optspecs: Vec<String> = Vec::new();
    for a in visible_args(cmd).filter(|a| !a.is_positional()) {
        let mut spec = String::new();
        let sh = shorts(a);
        let lo = longs(a);
        if let Some(s) = sh.first() {
            spec.push(*s);
        }
        if let Some(l) = lo.first() {
            if !spec.is_empty() {
                spec.push('/');
            }
            spec.push_str(l);
        }
        if takes_value(a) {
            spec.push('=');
        }
        optspecs.push(spec);
    }

    let mut out = format!(
        "# Print an optspec for argparse to handle cmd's options that are independent of any subcommand.
function {base}_global_optspecs
\tstring join \\n {specs}
end

function {base}_needs_command
\t# Figure out if the current invocation already has a command.
\tset -l cmd (commandline -opc)
\tset -e cmd[1]
\targparse -s ({base}_global_optspecs) -- $cmd 2>/dev/null
\tor return
\tif set -q argv[1]
\t\t# Also print the command, so this can be used to figure out what it is.
\t\techo $argv[1]
\t\treturn 1
\tend
\treturn 0
end

function {base}_using_subcommand
\tset -l cmd ({base}_needs_command)
\ttest -z \"$cmd\"
\tand return 1
\tcontains -- $cmd[1] $argv
end

",
        base = fn_base,
        specs = optspecs.join(" ")
    );

    for (path, c) in all_commands(cmd) {
        let condition = match path.len() {
            0 => format!("{}_needs_command", fn_base),
            1 => {
                let subs: Vec<&str> = visible_subcommands(c).map(|s| s.get_name()).collect();
                if subs.is_empty() {
                    format!("{}_using_subcommand {}", fn_base, path[0])
                } else {
                    format!(
                        "{}_using_subcommand {}; and not __fish_seen_subcommand_from {}",
                        fn_base,
                        path[0],
                        subs.join(" ")
                    )
                }
            }
            _ => {
                let mut cond = format!("{}_using_subcommand {}", fn_base, path[0]);
                for p in &path[1..] {
                    let _ = write!(cond, "; and __fish_seen_subcommand_from {}", p);
                }
                let subs: Vec<&str> = visible_subcommands(c).map(|s| s.get_name()).collect();
                if !subs.is_empty() {
                    let _ = write!(cond, "; and not __fish_seen_subcommand_from {}", subs.join(" "));
                }
                cond
            }
        };
        let preamble = format!("complete -c {} -n \"{}\"", bin_name, condition);

        for a in visible_args(c).filter(|a| !a.is_positional()) {
            let mut line = preamble.clone();
            for s in shorts(a) {
                let _ = write!(line, " -s {}", s);
            }
            for l in longs(a) {
                let _ = write!(line, " -l {}", l);
            }
            let help = help_text(a);
            if !help.is_empty() {
                let _ = write!(line, " -d '{}'", single_quote(&help));
            }
            if takes_value(a) {
                line.push_str(" -r");
                let vals = possible_values(a);
                if !vals.is_empty() {
                    let items: Vec<String> = vals.iter().map(|v| format!("{}\\t''", v)).collect();
                    let _ = write!(line, " -f -a \"{{{}}}\"", items.join(","));
                } else {
                    match a.get_value_hint() {
                        ValueHint::Unknown | ValueHint::AnyPath | ValueHint::FilePath => {}
                        ValueHint::Other => line.push_str(" -f"),
                        ValueHint::DirPath => line.push_str(" -f -a \"(__fish_complete_directories)\""),
                        ValueHint::ExecutablePath => line.push_str(" -f -a \"(__fish_complete_command)\""),
                        ValueHint::CommandName | ValueHint::CommandString | ValueHint::CommandWithArguments => {
                            line.push_str(" -f -a \"(__fish_complete_command)\"")
                        }
                        ValueHint::Username => line.push_str(" -f -a \"(__fish_complete_users)\""),
                        ValueHint::Hostname => line.push_str(" -f -a \"(__fish_print_hostnames)\""),
                        _ => {}
                    }
                }
            }
            line.push('\n');
            out.push_str(&line);
        }

        for sub in visible_subcommands(c) {
            let mut line = preamble.clone();
            if path.is_empty() {
                let _ = write!(line, " -a \"{}\"", sub.get_name());
            } else {
                let _ = write!(line, " -f -a \"{}\"", sub.get_name());
            }
            let about = about_text(sub);
            if !about.is_empty() {
                let _ = write!(line, " -d '{}'", single_quote(&about));
            }
            line.push('\n');
            out.push_str(&line);
        }
    }

    out
}

// ---------------------------------------------------------------------------
// elvish

fn elvish(cmd: &Command, bin_name: &str) -> String {
    let mut entries = String::new();
    for (path, c) in all_commands(cmd) {
        let mut key = bin_name.to_string();
        for p in &path {
            key.push(';');
            key.push_str(p);
        }
        let _ = write!(entries, "        &'{}'= {{\n", key);
        for a in visible_opts(c) {
            let help = single_quote(&help_text(a));
            for s in shorts(a) {
                let _ = write!(entries, "            cand -{} '{}'\n", s, help);
            }
            for l in longs(a) {
                let _ = write!(entries, "            cand --{} '{}'\n", l, help);
            }
        }
        for a in visible_flags(c) {
            let help = single_quote(&help_text(a));
            for s in shorts(a) {
                let _ = write!(entries, "            cand -{} '{}'\n", s, help);
            }
            for l in longs(a) {
                let _ = write!(entries, "            cand --{} '{}'\n", l, help);
            }
        }
        for sub in visible_subcommands(c) {
            let _ = write!(
                entries,
                "            cand {} '{}'\n",
                sub.get_name(),
                single_quote(&about_text(sub))
            );
        }
        entries.push_str("        }\n");
    }

    format!(
        "
use builtin;
use str;

set edit:completion:arg-completer[{bin}] = {{|@words|
    fn spaces {{|n|
        builtin:repeat $n ' ' | str:join ''
    }}
    fn cand {{|text desc|
        edit:complex-candidate $text &display=$text' '(spaces (- 14 (wcswidth $text)))$desc
    }}
    var command = '{bin}'
    for word $words[1..-1] {{
        if (str:has-prefix $word '-') {{
            break
        }}
        set command = $command';'$word
    }}
    var completions = [
{entries}    ]
    $completions[$command]
}}
",
        bin = bin_name,
        entries = entries
    )
}

// ---------------------------------------------------------------------------
// powershell

fn powershell(cmd: &Command, bin_name: &str) -> String {
    let mut entries = String::new();
    for (path, c) in all_commands(cmd) {
        let mut key = bin_name.to_string();
        for p in &path {
            key.push(';');
            key.push_str(p);
        }
        let _ = write!(entries, "        '{}' {{\n", key);
        let mut emit_arg = |a: &Arg| {
            let help = help_text(a);
            for s in shorts(a) {
                let tooltip = if help.is_empty() { format!("-{}", s) } else { help.clone() };
                // PowerShell is case-insensitive; distinguish upper-case
                // short flags with a trailing space.
                let list_item = if s.is_uppercase() {
                    format!("-{} ", s)
                } else {
                    format!("-{}", s)
                };
                let _ = write!(
                    entries,
                    "            [CompletionResult]::new('-{}', '{}', [CompletionResultType]::ParameterName, '{}')\n",
                    s,
                    list_item,
                    single_quote(&tooltip)
                );
            }
            for l in longs(a) {
                let tooltip = if help.is_empty() { format!("--{}", l) } else { help.clone() };
                let _ = write!(
                    entries,
                    "            [CompletionResult]::new('--{}', '--{}', [CompletionResultType]::ParameterName, '{}')\n",
                    l,
                    l,
                    single_quote(&tooltip)
                );
            }
        };
        for a in visible_opts(c) {
            emit_arg(a);
        }
        for a in visible_flags(c) {
            emit_arg(a);
        }
        for sub in visible_subcommands(c) {
            let about = about_text(sub);
            let tooltip = if about.is_empty() { sub.get_name().to_string() } else { about };
            let _ = write!(
                entries,
                "            [CompletionResult]::new('{}', '{}', [CompletionResultType]::ParameterValue, '{}')\n",
                sub.get_name(),
                sub.get_name(),
                single_quote(&tooltip)
            );
        }
        entries.push_str("            break\n        }\n");
    }

    format!(
        "
using namespace System.Management.Automation
using namespace System.Management.Automation.Language

Register-ArgumentCompleter -Native -CommandName '{bin}' -ScriptBlock {{
    param($wordToComplete, $commandAst, $cursorPosition)

    $commandElements = $commandAst.CommandElements
    $command = @(
        '{bin}'
        for ($i = 1; $i -lt $commandElements.Count; $i++) {{
            $element = $commandElements[$i]
            if ($element -isnot [StringConstantExpressionAst] -or
                $element.StringConstantType -ne [StringConstantType]::BareWord -or
                $element.Value.StartsWith('-') -or
                $element.Value -eq $wordToComplete) {{
                break
        }}
        $element.Value
    }}) -join ';'

    $completions = @(switch ($command) {{
{entries}    }})

    $completions.Where{{ $_.CompletionText -like \"$wordToComplete*\" }} |
        Sort-Object -Property ListItemText
}}
",
        bin = bin_name,
        entries = entries
    )
}
EOF
