    pub beg: usize,
    pub end: usize,
}

impl Row {
    pub const EMPTY: Row = Row {
        beg: usize::MAX,
        end: 1,
    };

    /// Widen this row so that it also covers the content of `line`.
    pub fn merge(&mut self, line: &str) {
        let mut first = None;
        let mut last = None;
        for (idx, ch) in line.char_indices() {
            if !ch.is_whitespace() {
                if first.is_none() {
                    first = Some(idx);
                }
                last = Some(idx);
            }
        }
        if let (Some(f), Some(l)) = (first, last) {
            self.beg = self.beg.min(f);
            self.end = self.end.max(l + 1);
        }
    }

    /// Apply the horizontal scale factor, truncating towards zero and
    /// saturating on overflow (NaN maps to zero).
    pub fn scaled(&self, hscale: f64) -> (usize, usize) {
        let beg = (self.beg as f64 * hscale) as usize;
        let end = (self.end as f64 * hscale) as usize;
        (beg, end)
    }
}

