    fn blank_lines_do_not_contribute() {
        let mut r = Row::EMPTY;
        r.merge("   ");
        assert_eq!(r, Row::EMPTY);
        r.merge("   abc");
        assert_eq!(r, Row { beg: 3, end: 6 });
        r.merge("");
        assert_eq!(r, Row { beg: 3, end: 6 });
