//! Core minimap rendering: groups source lines into rows, rows into
//! braille cells, and writes the result out.

use std::io::{self, Write};

use crate::row::Row;

/// How input bytes are interpreted.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Encoding {
    /// Invalid sequences are replaced with U+FFFD.
    Utf8Lossy,
    /// Invalid sequences are a hard error.
    Utf8,
}

#[derive(Clone, Debug)]
pub struct Options {
    pub hscale: f64,
    pub vscale: f64,
    pub padding: Option<usize>,
    pub encoding: Encoding,
}

/// Braille dot bit for cell row `r` (0..4) and cell column `c` (0..2).
const DOTS: [[u8; 2]; 4] = [[0x01, 0x08], [0x02, 0x10], [0x04, 0x20], [0x40, 0x80]];

/// Number of rows packed into a single output line.
const ROWS_PER_LINE: usize = 4;

pub struct Renderer<'a, W: Write> {
    opts: &'a Options,
    out: &'a mut W,
    rows: Vec<Row>,
    cur_row: Option<usize>,
    line_no: usize,
    cells: Vec<u8>,
    text: String,
}

impl<'a, W: Write> Renderer<'a, W> {
    pub fn new(opts: &'a Options, out: &'a mut W) -> Self {
        Renderer {
            opts,
            out,
            rows: Vec::with_capacity(ROWS_PER_LINE),
            cur_row: None,
            line_no: 0,
            cells: Vec::new(),
            text: String::new(),
        }
    }

    /// Register the arrival of the next source line (whether or not it could
    /// actually be decoded).  Flushes a completed group of rows when the new
    /// line starts a fresh row.
    pub fn begin_line(&mut self) -> io::Result<()> {
        let row = (self.line_no as f64 * self.opts.vscale) as usize;
        self.line_no += 1;
        if self.cur_row != Some(row) {
            if self.rows.len() == ROWS_PER_LINE {
                self.flush_rows()?;
            }
            self.rows.push(Row::EMPTY);
            self.cur_row = Some(row);
        }
        Ok(())
    }

    /// Merge the content of the current source line into the current row.
    pub fn feed(&mut self, line: &str) {
        if let Some(row) = self.rows.last_mut() {
            row.merge(line);
        }
    }

    /// Flush whatever rows are still pending.
    pub fn finish(mut self) -> io::Result<()> {
        if !self.rows.is_empty() {
            self.flush_rows()?;
        }
        Ok(())
    }

    fn flush_rows(&mut self) -> io::Result<()> {
        let mut scaled = [(0usize, 0usize); ROWS_PER_LINE];
        let mut width = 0usize;
        for (i, row) in self.rows.iter().enumerate() {
            scaled[i] = row.scaled(self.opts.hscale);
            width = width.max(scaled[i].1);
        }
        let n = self.rows.len();
        self.rows.clear();
        self.paint(&scaled[..n], width);
        let text = &self.text;
        match self.opts.padding {
            Some(pad) => writeln!(self.out, "{:<width$}", text, width = pad),
            None => writeln!(self.out, "{}", text),
        }
    }

    /// Render the scaled row extents into `self.text` as braille characters.
    fn paint(&mut self, scaled: &[(usize, usize)], width: usize) {
        let ncells = width / 2 + width % 2;
        let cells = &mut self.cells;
        cells.clear();
        cells.resize(ncells, 0);

        for (r, &(b, e)) in scaled.iter().enumerate() {
            if b >= e {
                continue;
            }
            let mut col = b;
            // Leading half cell.
            if col % 2 == 1 {
                cells[col / 2] |= DOTS[r][1];
                col += 1;
            }
            // Fully covered cells.
            let both = DOTS[r][0] | DOTS[r][1];
            let full_end = e - (e % 2);
            if col < full_end {
                for cell in &mut cells[col / 2..full_end / 2] {
                    *cell |= both;
                }
                col = full_end;
            }
            // Trailing half cell.
            if col < e {
                cells[col / 2] |= DOTS[r][0];
            }
        }

        let text = &mut self.text;
        text.clear();
        text.reserve(ncells * 3);
        for &c in cells.iter() {
            // 0x2800 + c is always a valid braille pattern code point.
            text.push(char::from_u32(0x2800 + c as u32).unwrap_or('\u{2800}'));
        }
    }
}
