//!
//! When an unknown `--long` flag is rejected with a suggestion, the usage
//! line lists the options that were already seen.  The options of the main
//! command form one logical group, and whenever any of them is involved the
//! whole group is shown as a single `<a|b|c>` alternative instead of the
//! individual options.  This module rewrites the usage context of such an
//! error accordingly.

use std::ffi::OsString;
use std::fmt::Write as _;

use clap::builder::StyledStr;
use clap::error::{ContextKind, ContextValue, ErrorKind};
use clap::parser::ValueSource;
use clap::{Command, Error};

/// Argument ids (in display order) that make up the option group of the
/// root command.
pub const ROOT_GROUP: [&str; 6] = ["file", "hscale", "vscale", "padding", "encoding", "version"];

/// Rewrite the usage line of `err` if it is an unknown-argument error with a
/// suggestion that involves the root option group.  `args` is the complete
/// command line (including the program name) that produced the error.
pub fn fix_suggestion_usage(cmd: &Command, args: &[OsString], mut err: Error) -> Error {
    if err.kind() != ErrorKind::UnknownArgument {
        return err;
    }
    let suggested = match err.get(ContextKind::SuggestedArg) {
        Some(ContextValue::String(s)) => s.clone(),
        _ => return err,
    };
    let invalid = match err.get(ContextKind::InvalidArg) {
        Some(ContextValue::String(s)) => s.clone(),
        _ => return err,
    };
    if !invalid.starts_with("--") {
        return err;
    }

    // Locate the offending token; everything before it has been parsed.
    let mut offending = None;
    for (i, a) in args.iter().enumerate().skip(1) {
        let Some(s) = a.to_str() else { continue };
        if s == "--" {
            return err;
        }
        let attached = s
            .strip_prefix(invalid.as_str())
            .map_or(false, |rest| rest.starts_with('='));
        if s == invalid || attached {
            offending = Some(i);
            break;
        }
    }
    let Some(end) = offending else {
        return err;
    };

    // Re-parse the already consumed part to learn which options were seen.
    let probe = cmd.clone().ignore_errors(true);
    let Ok(seen) = probe.try_get_matches_from(&args[..end]) else {
        return err;
    };
    if seen.subcommand_name().is_some() {
        return err;
    }

    let suggested_long = suggested.trim_start_matches('-');
    let suggested_id = cmd
        .get_arguments()
        .find(|a| a.get_long() == Some(suggested_long))
        .map(|a| a.get_id().as_str());
    let suggested_in_group = suggested_id.map_or(false, |id| ROOT_GROUP.contains(&id));
    let group_seen = ROOT_GROUP
        .iter()
        .any(|id| seen.value_source(id) == Some(ValueSource::CommandLine));
    if !(suggested_in_group || group_seen) {
        return err;
    }

    let styles = cmd.get_styles();
    let usage = styles.get_usage();
    let literal = styles.get_literal();
    let placeholder = styles.get_placeholder();
    let bin = cmd.get_bin_name().unwrap_or_else(|| cmd.get_name());

    let mut text = String::new();
    let _ = write!(text, "{usage}Usage:{usage:#} {literal}{bin}{literal:#} ");
    if !suggested_in_group {
        let _ = write!(text, "{literal}{suggested}{literal:#} ");
    }
    let members: Vec<String> = ROOT_GROUP
        .iter()
        .filter_map(|id| cmd.get_arguments().find(|a| a.get_id() == id))
        .map(|a| {
            if a.is_positional() {
                a.get_value_names()
                    .and_then(|v| v.first())
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| a.get_id().to_string().to_uppercase())
            } else {
                a.to_string()
            }
        })
        .collect();
    let _ = write!(text, "{placeholder}<{}>{placeholder:#}", members.join("|"));

    err.insert(ContextKind::Usage, ContextValue::StyledStr(StyledStr::from(text)));
    err
}
