//! Shell completion script generation.
//!
//! The scripts are produced by walking the (fully built) clap [`Command`]
//! tree, so they always reflect the actual CLI definition.  Each supported
//! shell lives in its own submodule.

mod bash;
mod elvish;
mod fish;
mod powershell;
mod zsh;

use std::io::Write;

use clap::{Arg, Command};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    PowerShell,
    Zsh,
}

impl Shell {
    /// Accepted spellings, in the order they are advertised to the user.
    pub const NAMES: [&'static str; 5] = ["bash", "elvish", "fish", "powershell", "zsh"];

    pub fn from_name(name: &str) -> Option<Shell> {
        match name {
            "bash" => Some(Shell::Bash),
            "elvish" => Some(Shell::Elvish),
            "fish" => Some(Shell::Fish),
            "powershell" => Some(Shell::PowerShell),
            "zsh" => Some(Shell::Zsh),
            _ => None,
        }
    }
}

/// Write the completion script for `shell` to `out`.
///
/// The script is rendered in full before anything is written; a failure to
/// write it is treated as fatal.
pub fn generate(shell: Shell, cmd: &mut Command, bin_name: &str, out: &mut dyn Write) {
    cmd.build();
    match shell {
        Shell::Bash => bash::generate(cmd, bin_name, out),
        Shell::Elvish => elvish::generate(cmd, bin_name, out),
        Shell::Fish => fish::generate(cmd, bin_name, out),
        Shell::PowerShell => powershell::generate(cmd, bin_name, out),
        Shell::Zsh => zsh::generate(cmd, bin_name, out),
    }
}

// ---------------------------------------------------------------------------
// Helpers shared by the shell specific generators.

/// Help text of an argument, flattened to a single line.
pub(crate) fn help_text(arg: &Arg) -> String {
    arg.get_help()
        .map(|h| h.to_string())
        .unwrap_or_default()
        .replace('\n', " ")
}

/// About text of a command, flattened to a single line.
pub(crate) fn about_text(cmd: &Command) -> String {
    cmd.get_about()
        .map(|h| h.to_string())
        .unwrap_or_default()
        .replace('\n', " ")
}

/// Names of the (visible) possible values of an argument.
pub(crate) fn possible_values(arg: &Arg) -> Vec<String> {
    arg.get_possible_values()
        .iter()
        .filter(|v| !v.is_hide_set())
        .map(|v| v.get_name().to_string())
        .collect()
}

pub(crate) fn takes_value(arg: &Arg) -> bool {
    arg.get_action().takes_values()
}

pub(crate) fn visible_args(cmd: &Command) -> impl Iterator<Item = &Arg> {
    cmd.get_arguments().filter(|a| !a.is_hide_set())
}

/// Visible non-positional arguments that take a value.
pub(crate) fn visible_opts(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| !a.is_positional() && takes_value(a))
}

/// Visible non-positional arguments that do not take a value.
pub(crate) fn visible_flags(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| !a.is_positional() && !takes_value(a))
}

pub(crate) fn visible_positionals(cmd: &Command) -> impl Iterator<Item = &Arg> {
    visible_args(cmd).filter(|a| a.is_positional())
}

pub(crate) fn visible_subcommands(cmd: &Command) -> impl Iterator<Item = &Command> {
    cmd.get_subcommands().filter(|c| !c.is_hide_set())
}

/// Short name plus visible short aliases.
pub(crate) fn shorts(arg: &Arg) -> Vec<char> {
    let mut v = Vec::new();
    if let Some(s) = arg.get_short() {
        v.push(s);
    }
