fn render(cmd: &Command, bin_name: &str) -> String {
    let func = format!("_{bin_name}");
    let root_id = command_id(bin_name, &[]);
    let cmds = all_commands(cmd);

    // Arms that track the subcommand path while scanning the words.
    let mut cases = String::new();
    for (path, c) in &cmds {
        let id = command_id(bin_name, path);
        for sub in visible_subcommands(c) {
            let mut p = path.clone();
            p.push(sub.get_name());
            let sub_id = command_id(bin_name, &p);
            let _ = write!(
                cases,
                "            {id},{name})\n                cmd=\"{sub_id}\"\n                ;;\n",
                name = sub.get_name(),
            );
        }
    }

    // One arm per command with its word list and option value handling.
    let mut bodies = String::new();
    for (path, c) in &cmds {
        let id = command_id(bin_name, path);
        let level = path.len() + 1;
        let opts = word_list(c);

        let mut prev_cases = String::new();
        for a in visible_opts(c) {
