//! Zsh completion script.
//!
//! Every command gets an `_arguments` call describing its options and
//! positionals; subcommands are dispatched through a `state` machine and
//! described by `_describe` helper functions.

use std::fmt::Write as _;
use std::io::Write;

use clap::{Arg, Command, ValueHint};

use super::{
    about_text, all_commands, help_text, longs, possible_values, shorts, single_quote,
    visible_flags, visible_opts, visible_positionals, visible_subcommands,
};

/// Name of the `_describe` helper listing the subcommands of a command.
fn commands_fn(bin_name: &str, path: &[&str]) -> String {
    let mut f = format!("_{bin_name}");
    for p in path {
        f.push_str("__");
        f.push_str(p);
    }
    f.push_str("_commands");
    f
}

/// Completion action for the value of an argument.
fn value_completion(arg: &Arg, positional: bool) -> String {
    let vals = possible_values(arg);
    if !vals.is_empty() {
        return format!("({})", vals.join(" "));
    }
    match arg.get_value_hint() {
        ValueHint::Unknown if positional => "_files".to_string(),
        ValueHint::Unknown => "_default".to_string(),
        ValueHint::Other => String::new(),
        ValueHint::AnyPath | ValueHint::FilePath => "_files".to_string(),
        ValueHint::DirPath => "_files -/".to_string(),
        ValueHint::ExecutablePath => "_absolute_command_paths".to_string(),
        ValueHint::CommandName => "_command_names -e".to_string(),
        ValueHint::CommandString => "_cmdstring".to_string(),
        ValueHint::CommandWithArguments => "_cmdambivalent".to_string(),
        ValueHint::Username => "_users".to_string(),
        ValueHint::Hostname => "_hosts".to_string(),
        ValueHint::Url => "_urls".to_string(),
        ValueHint::EmailAddress => "_email_addresses".to_string(),
        _ => String::new(),
    }
}

/// Render the script for `cmd` and write it to `out`.
pub fn generate(cmd: &Command, bin_name: &str, out: &mut dyn Write) {
    let script = render(cmd, bin_name);
    out.write_all(script.as_bytes())
        .expect("failed to write completion file");
}

fn render(cmd: &Command, bin_name: &str) -> String {
    let func = format!("_{bin_name}");
    let mut body = String::new();
    arguments(cmd, bin_name, &[], &mut body);

    let mut describe = String::new();
    for (path, c) in all_commands(cmd) {
        let fname = commands_fn(bin_name, &path);
        let mut desc_name = bin_name.to_string();
        for p in &path {
            desc_name.push(' ');
            desc_name.push_str(p);
        }
        let subs: Vec<&Command> = visible_subcommands(c).collect();
        let _ = write!(describe, "(( $+functions[{fname}] )) ||\n{fname}() {{\n");
        if subs.is_empty() {
            describe.push_str("    local commands; commands=()\n");
        } else {
            describe.push_str("    local commands; commands=(\n");
            for sub in subs {
                let _ = write!(
                    describe,
                    "'{}:{}' \\\n",
                    sub.get_name(),
                    single_quote(&about_text(sub))
                );
            }
            describe.push_str("    )\n");
        }
        let _ = write!(
            describe,
            "    _describe -t commands '{desc_name} commands' commands \"$@\"\n}}\n",
        );
    }

    format!(
        "#compdef {bin_name}

autoload -U is-at-least

{func}() {{
    typeset -A opt_args
    typeset -a _arguments_options
    local ret=1

    if is-at-least 5.2; then
        _arguments_options=(-s -S -C)
    else
        _arguments_options=(-s -C)
    fi

    local context curcontext=\"$curcontext\" state line
{body}}}

{describe}
if [ \"$funcstack[1]\" = \"{func}\" ]; then
    {func} \"$@\"
else
    compdef {func} {bin_name}
fi
",
    )
}

/// Emit the `_arguments` call for `cmd` (and, recursively, for its
/// subcommands) into `out`.
fn arguments(cmd: &Command, bin_name: &str, path: &[&str], out: &mut String) {
    let depth = path.len();
    let state_name = if depth == 0 {
        bin_name.to_string()
    } else {
        path[depth - 1].to_string()
    };
    let indent = if depth == 0 { "    " } else { "" };

    let _ = writeln!(out, "{indent}_arguments \"${{_arguments_options[@]}}\" : \\");

    for a in visible_opts(cmd) {
        let help = single_quote(&help_text(a));
        let value_name = a
            .get_value_names()
            .and_then(|v| v.first())
            .map(|s| s.to_string())
            .unwrap_or_else(|| a.get_id().to_string().to_uppercase());
        let completion = value_completion(a, false);
        for s in shorts(a) {
            let _ = writeln!(out, "'-{s}+[{help}]:{value_name}:{completion}' \\");
        }
        for l in longs(a) {
            let _ = writeln!(out, "'--{l}=[{help}]:{value_name}:{completion}' \\");
        }
    }
    for a in visible_flags(cmd) {
        let help = single_quote(&help_text(a));
        for s in shorts(a) {
            let _ = writeln!(out, "'-{s}[{help}]' \\");
        }
        for l in longs(a) {
            let _ = writeln!(out, "'--{l}[{help}]' \\");
        }
    }
    for a in visible_positionals(cmd) {
        let multiple = a.get_num_args().map_or(false, |n| n.max_values() > 1);
        let cardinality = if multiple {
            "*"
        } else if a.is_required_set() {
            ""
        } else {
            ":"
        };
        let help = help_text(a);
        let help = if help.is_empty() {
            String::new()
        } else {
            format!(" -- {}", single_quote(&help))
        };
        let completion = value_completion(a, true);
        let _ = writeln!(
            out,
            "'{cardinality}:{}{help}:{completion}' \\",
            a.get_id()
        );
    }

    let subs: Vec<&Command> = visible_subcommands(cmd).collect();
    if !subs.is_empty() {
        let _ = writeln!(out, "\":: :{}\" \\", commands_fn(bin_name, path));
        let _ = writeln!(out, "\"*::: :->{state_name}\" \\");
    }
    out.push_str("&& ret=0\n");

    if subs.is_empty() {
        return;
    }

