//! Fish completion script.
//!
//! Fish completions are declarative: one `complete` command per option or
//! subcommand, guarded by a condition (`-n`) that checks which subcommand
//! is currently being completed.  The script starts with three helper
//! functions:
//!
//! * `__fish_<bin>_global_optspecs` lists the top level options in fish's
//!   `argparse` optspec syntax,
//! * `__fish_<bin>_needs_command` succeeds when no subcommand has been typed
//!   yet (and prints the subcommand otherwise), and
//! * `__fish_<bin>_using_subcommand` succeeds when the given subcommand is
//!   the one being completed.

use std::fmt::Write as _;
use std::io::Write;

use clap::{Arg, Command, ValueHint};

use super::{
    about_text, all_commands, help_text, longs, possible_values, shorts, single_quote, takes_value,
    visible_args, visible_subcommands,
};

/// Prefix shared by all helper functions: `__fish_<bin>` with dashes
/// replaced by underscores so it forms a valid identifier.
fn function_base(bin_name: &str) -> String {
    format!("__fish_{}", bin_name.replace('-', "_"))
}

/// `argparse` optspec for one non-positional argument, e.g. `H/horizontal-scale=`.
///
/// The spec consists of the short name and the long name separated by a
/// slash (either may be absent) followed by `=` when the option takes a
/// value.
