//! Usage line rendering for "did you mean" errors.
//!
//! When an unknown `--long` flag is rejected with a suggestion, the usage
//! line lists the arguments that were already seen plus the suggested one.
//! Arguments that belong to an [`ArgGroup`](clap::ArgGroup) are not listed
//! individually: as soon as one member is involved the whole group is shown
//! as a single `<a|b|c>` alternative.  This module rewrites the usage
//! context of such an error accordingly.

use std::ffi::OsString;
use std::fmt::Write as _;

use clap::builder::StyledStr;
use clap::error::{ContextKind, ContextValue, ErrorKind};
use clap::parser::ValueSource;
use clap::{Arg, Command, Error};

/// Rewrite the usage line of `err` if it is an unknown-argument error with a
/// suggestion that involves an argument group.  `args` is the complete
/// command line (including the program name) that produced the error.
pub fn fix_suggestion_usage(cmd: &Command, args: &[OsString], mut err: Error) -> Error {
    if err.kind() != ErrorKind::UnknownArgument {
        return err;
    }
    let suggested = match err.get(ContextKind::SuggestedArg) {
        Some(ContextValue::String(s)) => s.clone(),
        _ => return err,
    };
    let invalid = match err.get(ContextKind::InvalidArg) {
        Some(ContextValue::String(s)) => s.clone(),
        _ => return err,
    };
    if !invalid.starts_with("--") {
        return err;
    }

    // Locate the offending token; everything before it has been parsed.
    let Some(end) = find_token(args, &invalid) else {
        return err;
    };

    // Re-parse the already consumed part to learn which arguments were seen.
    let probe = cmd.clone().ignore_errors(true);
    let Ok(seen) = probe.try_get_matches_from(&args[..end]) else {
        return err;
    };
    if seen.subcommand_name().is_some() {
        return err;
    }

    let suggested_id = cmd
        .get_arguments()
        .find(|a| a.get_long() == Some(suggested.trim_start_matches('-')))
        .map(|a| a.get_id().clone());
    let involved = |a: &Arg| {
        suggested_id.as_ref() == Some(a.get_id())
            || seen.value_source(a.get_id().as_str()) == Some(ValueSource::CommandLine)
    };

    // Groups with at least one involved member are rendered as a whole.
    let mut groups: Vec<Vec<&Arg>> = Vec::new();
    for group in cmd.get_groups() {
        let members: Vec<&Arg> = group
            .get_args()
            .filter_map(|id| cmd.get_arguments().find(|a| a.get_id() == id))
            .collect();
        if members.iter().any(|a| involved(a)) {
            groups.push(members);
        }
    }
    if groups.is_empty() {
        return err;
    }
    let in_group = |a: &Arg| groups.iter().flatten().any(|m| m.get_id() == a.get_id());

    let styles = cmd.get_styles();
    let usage = styles.get_usage();
    let literal = styles.get_literal();
    let placeholder = styles.get_placeholder();
    let bin = cmd.get_bin_name().unwrap_or_else(|| cmd.get_name());

    let mut text = String::new();
    let _ = write!(text, "{usage}Usage:{usage:#} {literal}{bin}{literal:#}");
    // Involved options outside of any rendered group come first ...
    for a in cmd.get_arguments().filter(|a| !a.is_positional()) {
        if involved(a) && !in_group(a) {
            let _ = write!(text, " {literal}{a}{literal:#}");
        }
    }
    // ... followed by the groups themselves.
    for members in &groups {
        let alternatives: Vec<String> = members.iter().map(|a| member_name(a)).collect();
        let _ = write!(
            text,
            " {placeholder}<{}>{placeholder:#}",
            alternatives.join("|")
        );
    }

