    err
}

/// Index of the first command line token spelling `flag` (optionally with an
/// attached `=value`), or `None` if it only occurs after a `--` terminator.
fn find_token(args: &[OsString], flag: &str) -> Option<usize> {
    for (i, a) in args.iter().enumerate().skip(1) {
        let Some(s) = a.to_str() else { continue };
        if s == "--" {
            return None;
        }
        let attached = s
            .strip_prefix(flag)
            .map_or(false, |rest| rest.starts_with('='));
        if s == flag || attached {
            return Some(i);
        }
    }
    None
}

/// How an argument appears inside a `<a|b|c>` group: positionals by their
/// value name, options by their full usage form.
fn member_name(arg: &Arg) -> String {
    if arg.is_positional() {
        arg.get_value_names()
            .and_then(|v| v.first())
            .map(|s| s.to_string())
            .unwrap_or_else(|| arg.get_id().to_string().to_uppercase())
    } else {
        arg.to_string()
    }
}
