        let Some(s) = a.to_str() else { continue };
        if s == "--" {
            return None;
        }
        let attached = s
            .strip_prefix(flag)
            .map_or(false, |rest| rest.starts_with('='));
        if s == flag || attached {
            return Some(i);
        }
    }
    None
}

